private static int decodeOctets(int i, ByteBuffer bb,StringBuilder sb) {
    // Ensure the input indices are within bounds
    if (i < 0 || i + 3 > bb.capacity()) {
        throw new IllegalArgumentException("Index out of range");
    }

    int decoded = 0;
    // Read a sequence of 4 bytes
    for (int j = 0; j < 4; j++) {
        decoded = decoded << 8;
        decoded += bb.get(i++);
    }

    // Determine the character length based on the highest byte of the extension byte
    int charLength = (decoded>>>8) & 0xf;

    // Append the decoded characters to the StringBuilder
    for (int j = 0; j < charLength; j++) {
        char c = (char) (decoded & 0xff);
        sb.append(c);
        decoded >>= 8;
    }

    return i;
}
