public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Validate if targetType is not a parameterized class
    if (!targetType.isParameterizedType()) {
        return null;
    }

    // Extract type parameters from targetType
    ParameterizedType parameterizedType = (ParameterizedType) targetType;

    // Validate if targetType has exactly one type parameter
    if (parameterizedType.getActualTypeArguments().length != 1) {
        return null;
    }

    // Get the actual type argument for the targetType
    Type argumentType = parameterizedType.getActualTypeArguments()[0];

    // Get the type parameter of genericType
    Type wildCardType = genericType;

    // Check if genericType is a wildcard type
    if (wildCardType instanceofWildcardType) {
        // Extract the upper bound of the wildcard type
        WildcardType wildCard = (WildcardType) wildCardType;
        Type upperBound = wildCard.getUpperBound();

        // Check if the upper bound is the actual type argument for the targetType
        if (upperBound.equals(argumentType)) {
            return new Class[args.length];
        } else {
            return null;
        }
    }

    // If genericType is not a wildcard type, look for a type variable match if available
    if (genericType instanceof WildcardType) {
        return null;
    } else if (wildType instanceof TypeVariable) {
        // Get the type variable name and check if it matches the actual type argument for the targetType
        TypeVariable<?> typeVariable = (TypeVariable<?>) wildType;
        String typeName = typeVariable.getName();
        if (typeName.equals(argumentType.getTypeName())) {
            return new Class[args.length];
        } else {
            return null;
        }
    }

    // If genericType is not a type parameter or a wildcard type, return null
    return null;
}
