import java.text.SimpleDateFormat;
import java.util.Date;

public class TimeBucketCompressor {
    public static long compressTimeBucket(long timeBucket, int dayStep) {
        // Handle invalid input
        if (timeBucket <= 0 || dayStep <= 0) {
            throw new IllegalArgumentException("Invalid input: timeBucket must be greater than 0 and dayStep must be greater than 0");
        }

        // Convert time bucket to a Date object
        Date before = new Date(timeBucket);

        // Create date objects for the start and end of the current dayStep
        Date start = new Date(timeBucket);
        start.setTime(start.getTime() - (timeBucket % dayStep) * 24 * 60 * 60 * 1000);
        start = new Date(start.getTime() + 23 * 60 * 60 * 1000 - 1);

        // Format the date objects as strings
        SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMdd");
        String startStr = sdf.format(start);
        String endStr = sdf.format(before);

        // Create a new time bucket based on the start and end dates
        long compressedTimeBucket = Long.parseLong(startStr) + 24 * 60 * 60 * 1000 * ((endStr.length() - startStr.length()) / 5);

        return compressedTimeBucket;
    }
}
