public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        int size = 0;
        int remainingLen = len;
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if (c > 0xFF) {
                size += 3;
            } else if (c > 0x7F) {
                size += 2;
            } else {
                size += 1;
            }
            if ((char) c == -1) { // Sign Extension for negative values
                size++;
            }
            remainingLen--;
        }
        return size;
    }
