public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("The URI cannot be null");
    }
    if (!u.isRelative()) {
        u = u.resolve("");
    }
    String path = u.getPath();
    List<PathSegmentImpl> result = new ArrayList<>();
    PathSegmentImpl current = new PathSegmentImpl();
    StringBuffer sb = new StringBuffer();
    for (int i = 0; i < path.length(); i++) {
        char c = path.charAt(i);
        if (c == '/') {
            if (!sb.isEmpty()) {
                current.setPath(sb.toString());
                result.add(current);
                sb.setLength(0);
            }
        } else if (c == '%') {
            if (i + 2 < path.length()) {
                char hex1 = path.charAt(i + 1);
                char hex2 = path.charAt(i + 2);
                int decodedValue = Integer.parseInt(String.valueOf(hex1) + String.valueOf(hex2), 16);
                sb.append((char) decodedValue);
                i += 2;
            } else {
                throw new IllegalArgumentException("Invalid percentage encoding");
            }
        } else {
            sb.append(c);
        }
    }
    if (!sb.isEmpty()) {
        current.setPath(sb.toString());
        result.add(current);
    }
    return result;
}
