    }
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i+1 == str.length() || str.charAt(i+1) != '\\') {
                result.append(c); // Directly append without escaping
            } else {
                result.append(c).append(str.charAt(i+1)); // Escape another backslash
                i++; // Skip the next character
            }
        } else {
            result.append(c); // No escape needed
        }
    }
    return result.toString();
}
