private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("MinLabel must be within the bucket indices.");
    }

    // Step 1: Clear the bucket with minLabel
    bucketsByLabel.get(minLabel).clear();
    labels.remove(minLabel);

    // Step 2: Move all vertices from the bucket with minLabel to the bucket with label 0
    for (int vertex : bucketsByLabel.get(minLabel)) {
        bucketsByLabel.get(0).add(vertex);
        labels.remove(vertex);
        labels.add(0, vertex);
    }

    // Step 3: Ensure the labels are correctly updated
    for (int i = 0; i < labels.size(); i++) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        } else if (labels.get(i) > minLabel) {
            labels.set(i, labels.get(i) - 1);
        }
    }
}
