    }

    // Extend the byte array if necessary
    if (data.length < size) {
        data = new byte[size];
    }

    // Write the integer value into the byte array
    data[data.length - 1 - size] = (byte) (intValue & 0xFF);

    // If intValue > 255, write the additional byte
