private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null || vertices.isEmpty()) {
        return true; // An empty graph is considered a clique by definition
    }

    // Check if every vertex is adjacent to every other vertex in the set of vertices
    for (V vertex : vertices) {
        if (vertices.contains(vertex)) {
            continue; // Skip the vertex itself
        }

        for (V other : vertices) {
            if (vertex.equals(other)) {
                continue; // Skip the same vertex again
            }
            if (!graph.hasEdge(vertex, other)) {
                return false;
            }
        }
    }
    return true;
}
