private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    final int numTypes = descriptor.length() - 1;
    final String[] types = descriptor.split(",");

    for (int i = 0; i < numTypes; i++) {
        if (!typeStack.isEmpty()) {
            if (types[i].equals(typeStack.peek())) {
                typeStack.pop();
            } else {
                throw new IllegalStateException("Descriptor does not match stack top type");
            }
        } else {
            throw new IllegalStateException("Descriptor has more types than are available on the stack");
        }
    }
}
