public class ThreadSnapshotParser {

    public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
        List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] data = line.split(", ");
                if (data.length != 5) {
                    throw new IllegalArgumentException("Invalid line format: " + line);
                }
                String threadId = data[0];
                double timestamp = Double.parseDouble(data[1]);
                String state = data[2];
                String priority = data[3];
                String classType = data[4];
                ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, timestamp, state, priority, classType);
                long timeRangeIndex = timeRanges.indexOf(ProfileAnalyzeTimeRange.parseFromString(data[0]));
                if (timeRangeIndex >= 0) {
                    threadSnapshots.add(timeRangeIndex, threadSnapshot);
                } else {
                    throw new IllegalArgumentException("ProfileAnalyzeTimeRange not found for threadId: " + threadId);
                }
            }
        }
        return threadSnapshots;
    }
}

class ProfileAnalyzeTimeRange {
    private String threadId;
    private String startTime;
    private String endTime;

    public ProfileAnalyzeTimeRange(String threadId, String startTime, String endTime) {
        this.threadId = threadId;
        this.startTime = startTime;
        this.endTime = endTime;
    }

    public static ProfileAnalyzeTimeRange parseFromString(String line) {
        String[] data = line.split(", ");
        if (data.length != 3) {
            throw new IllegalArgumentException("Invalid line format: " + line);
        }
        String threadId = data[0];
        String startTime = data[1];
        String endTime = data[2];
        return new ProfileAnalyzeTimeRange(threadId, startTime, endTime);
    }

    @Override
    public String toString() {
        return "ProfileAnalyzeTimeRange{" +
                "threadId='" + threadId + '\'' +
                ", startTime='" + startTime + '\'' +
                ", endTime='" + endTime + '\'' +
                '}';
    }
}
